formula_sources.getSystemItemSellValue:
function getSystemItemSellValue(itemId, meta) {
                    const price = parseInt(itemSellPrices[itemId] || 0, 10) || 0;
                    if (price > 0) return price;

                    const itemScore = getItemScore(meta || {});
                    return Math.max(50, (itemScore > 0 ? itemScore : 10) * 2);
                }

formula_sources.getItemScore:
function getItemScore(meta) {
                    const attrs = meta.attributes || {};
                    return (parseInt(meta.attack ?? attrs.attack ?? 0) || 0)
                        + (parseInt(meta.defense ?? attrs.defense ?? 0) || 0)
                        + (parseInt(meta.armor ?? attrs.armor ?? 0) || 0);
                }

formula_sources.getItemMarketCategory:
function getItemMarketCategory(meta) {
                    if (!meta) return 'other';
                    const slot = String(meta.slot || '').toLowerCase();
                    const known = ['helmet', 'armor', 'legs', 'boots', 'shield', 'ring', 'amulet', 'ammo', 'potion', 'rune'];
                    if (known.includes(slot)) return slot;

                    const name = String(meta.name || '').toLowerCase();
                    if (name.includes('helmet') || name.includes('hat') || name.includes('circlet') || name.includes('hood') || name.includes('crown')) return 'helmet';
                    if (name.includes('armor') || name.includes('hauberk') || name.includes('robe') || name.includes('coat') || name.includes('mail') || name.includes('doublet')) return 'armor';
                    if (name.includes('legs') || name.includes('kilt') || name.includes('pants') || name.includes('trousers')) return 'legs';
                    if (name.includes('boots') || name.includes('shoes')) return 'boots';
                    if (name.includes('shield') || name.includes('defender')) return 'shield';

                    if (slot !== 'weapon' && slot !== '') return 'other';

                    const wtype = String(meta.weapontype || '').toLowerCase();

                    if (wtype === 'sword' || name.includes('sword') || name.includes('blade') || name.includes('slicer') || name.includes('dagger') || name.includes('rapier') || name.includes('saber')) {
                        return 'sword';
                    }
                    if (wtype === 'axe' || name.includes('axe') || name.includes('halberd') || name.includes('chopper') || name.includes('hatchet')) {
                        return 'axe';
                    }
                    if (wtype === 'club' || name.includes('club') || name.includes('mace') || name.includes('hammer') || name.includes('spear') || (wtype !== 'wand' && name.includes('staff')) || name.includes('morning star') || name.includes('scepter')) {
                        return 'club';
                    }
                    if (wtype === 'wand' || name.includes('wand') || name.includes('rod')) {
                        return 'wand';
                    }
                    if (wtype === 'distance' || name.includes('bow') || name.includes('crossbow') || name.includes('arbalest')) {
                        return 'ranged';
                    }

                    return 'other';
                }

formula_sources.getItemTooltipStats:
function getItemTooltipStats(meta, isEquippedItem = false) {
                    const attrs = meta.attributes || {};
                    const slot = meta.slot || '';
                    const attack = parseInt(meta.attack ?? attrs.attack ?? 0) || 0;
                    const defense = parseInt(meta.defense ?? attrs.defense ?? 0) || 0;
                    const extraDefense = parseInt(meta.extradef ?? attrs.extradef ?? 0) || 0;
                    const armor = parseInt(meta.armor ?? attrs.armor ?? 0) || 0;
                    const level = parseInt(meta.level || 0, 10) || 0;
                    const range = parseInt(meta.range || 0, 10) || 0;
                    const hitChance = parseInt(meta.hitchance || 0, 10) || 0;
                    const maxHitChance = parseInt(meta.maxhitchance || 0, 10) || 0;
                    const weight = parseFloat(meta.weight || 0) || 0;
                    const lines = [];

                    // Arma elemental: detalha a divisão real do golpe em vez de só o total.
                    const elementAtkTip = parseInt(meta.element_attack || 0, 10) || 0;
                    const elementTypeTip = String(meta.element_type || '');
                    // Físico derivado do total (inclui bônus Elite, que é sempre físico).
                    const baseAtkTip = Math.max(0, attack - elementAtkTip);
                    let attackSuffix = (elementAtkTip > 0 && elementTypeTip)
                        ? ` (${baseAtkTip} físico + ${elementAtkTip} ${getElementLabelPt(elementTypeTip)})`
                        : '';

                    // IMBUIÇÃO: sobrescreve a divisão mostrada, porque ela sobrescreve o
                    // elemento nato no combate também (ver getWeaponElementSplit). Sem isso o
                    // tooltip de uma soulshredder imbuída de fogo continuaria anunciando gelo.
                    // ⚠️ A ORDEM AQUI IMPORTA — foi ela que causava o "demora pra atualizar".
                    // Antes, `meta.imbuement` tinha PRIORIDADE sobre getActiveImbuement(). Só
                    // que meta.imbuement vem de playerEquip, que é o estado carregado com a
                    // página e NÃO é atualizado por imbueItem(); getActiveImbuement() lê o
                    // playerState.weaponImbuement, que É atualizado na hora. Resultado: o valor
                    // VELHO ganhava do NOVO, e o tooltip só corrigia no próximo sync (45-60s).
                    //
                    // Agora a arma equipada usa sempre a fonte viva. Item que não está equipado
                    // não mostra imbuição nenhuma: ela é estado da arma em uso, não propriedade
                    // do item — mochila, depósito e Market usam esta mesma função.
                    const tipImbue = (isEquippedItem && slot === 'weapon') ? getActiveImbuement() : null;
                    if (tipImbue && attack > 0) {
                        const elemPart = Math.round(attack * IMBUE_ELEMENT_SHARE);
                        const physPart = Math.max(0, attack - elemPart);
                        attackSuffix = ` (${physPart} físico + ${elemPart} ${getElementLabelPt(tipImbue.element)})`;
                    }

                    // Imbuição de DEFESA (2026-08-02): mesma regra de "só na peça equipada",
                    // mas para o slot armor — e ela não mexe no ataque, só acrescenta a linha
                    // de resistência mais abaixo.
                    const tipArmorImbue = (isEquippedItem && slot === 'armor') ? getActiveArmorImbuement() : null;

                    if (slot === 'weapon' || slot === 'ammo') {
                        if (attack > 0) lines.push(`Attack: ${attack}${attackSuffix}`);
                        // TEXTO PURO, sem HTML: todas as linhas passam por escapeTooltipLine()
                        // no return desta função, então qualquer tag viraria texto visível.
                        if (tipImbue) {
                            lines.push(`✨ Imbuída: ${IMBUE_LABELS[tipImbue.element]} (${formatImbueRemaining(tipImbue.until)})`);
                        }
                        if (defense > 0) lines.push(`Defense: ${defense}${extraDefense !== 0 ? ` +${extraDefense}` : ''}`);
                        if (range > 0) lines.push(`Range: ${range}`);
                        if (hitChance !== 0) lines.push(`Hit Chance: ${hitChance > 0 ? '+' : ''}${hitChance}%`);
                        if (maxHitChance > 0) lines.push(`Max Hit Chance: ${maxHitChance}%`);
                    } else if (slot === 'shield') {
                        if (defense > 0) lines.push(`Defense: ${defense}${extraDefense !== 0 ? ` +${extraDefense}` : ''}`);
                    } else {
                        if (armor > 0) lines.push(`Armor: ${armor}`);
                        if (defense > 0) lines.push(`Defense: ${defense}${extraDefense !== 0 ? ` +${extraDefense}` : ''}`);
                    }

                    // Linha da imbuição de DEFESA. TEXTO PURO, sem HTML — todas as linhas
                    // passam por escapeTooltipLine() no return, então tag viraria texto visível.
                    if (tipArmorImbue) {
                        lines.push(`🛡️ Imbuída: ${IMBUE_LABELS[tipArmorImbue.element]} +${IMBUE_ARMOR_RESIST_PCT}% resist. (${formatImbueRemaining(tipArmorImbue.until)})`);
                    }

                    if (level > 0) lines.push(`Required Level: ${level}`);

                    const magicPoints = parseInt(meta.magicpoints || 0);
                    const maxHP = parseInt(meta.maxhealth || 0);
                    const maxMana = parseInt(meta.maxmana || 0);

                    const skillDist = parseInt(meta.skilldist || 0);
                    const skillSword = parseInt(meta.skillsword || 0);
                    const skillAxe = parseInt(meta.skillaxe || 0);
                    const skillClub = parseInt(meta.skillclub || 0);
                    const skillShield = parseInt(meta.skillshield || 0);
                    const skillFist = parseInt(meta.skillfist || 0);

                    if (magicPoints > 0) lines.push(`Magic Level: +${magicPoints}`);
                    if (maxHP > 0) lines.push(`Max Health: +${maxHP}`);
                    if (maxMana > 0) lines.push(`Max Mana: +${maxMana}`);

                    if (skillDist > 0) lines.push(`Distance: +${skillDist}`);
                    if (skillSword > 0) lines.push(`Sword Fighting: +${skillSword}`);
                    if (skillAxe > 0) lines.push(`Axe Fighting: +${skillAxe}`);
                    if (skillClub > 0) lines.push(`Club Fighting: +${skillClub}`);
                    if (skillShield > 0) lines.push(`Shielding: +${skillShield}`);
                    if (skillFist > 0) lines.push(`Fist Fighting: +${skillFist}`);

                    const itemCritChance = parseInt(meta.crit_chance || 0, 10) || 0;
                    const itemCritDmg = parseInt(meta.crit_damage || 0, 10) || 0;
                    const itemLifeLeech = parseInt(meta.life_leech_amount || 0, 10) || 0;
                    const itemManaLeech = parseInt(meta.mana_leech_amount || 0, 10) || 0;
                    const itemReflect = parseInt(meta.reflect || 0, 10) || 0;
                    const itemReflectChance = parseInt(meta.reflect_chance || 20, 10) || 20;

                    if (itemCritChance > 0) lines.push(`Critical Hit Chance: +${itemCritChance}%`);
                    if (itemCritDmg > 0) lines.push(`Critical Extra Damage: +${itemCritDmg}%`);
                    if (itemLifeLeech > 0) lines.push(`Life Leech: +${itemLifeLeech}%`);
                    if (itemManaLeech > 0) lines.push(`Mana Leech: +${itemManaLeech}%`);
                    if (itemReflect > 0) lines.push(`Reflect: +${itemReflect}% (${itemReflectChance}% chance)`);

                    const speed = parseInt(meta.speed || 0, 10) || 0;
                    if (speed !== 0) {
                        lines.push(`Speed: ${speed > 0 ? '+' : ''}${speed}`);
                        lines.push('Speed a partir de 40 acelera a próxima leva.');
                    }

                    const charges = parseInt(meta.charges || 0, 10) || 0;
                    if (charges > 0) lines.push(`Charges: ${charges}`);

                    const duration = parseInt(meta.duration || 0, 10) || 0;
                    if (duration > 0) lines.push(`Tempo de uso: ${formatItemDuration(duration)}`);

                    if (meta.active_item_name) {
                        lines.push(`Ao equipar: ${meta.active_item_name}`);
                        const activeDuration = parseInt(meta.active_duration || 0, 10) || 0;
                        if (activeDuration > 0) lines.push(`Tempo ativo: ${formatItemDuration(activeDuration)}`);
                    }

                    if (parseInt(meta.manashield || meta.active_manashield || 0, 10)) lines.push('Efeito: Magic Shield');
                    if (parseInt(meta.invisible || meta.active_invisible || 0, 10)) lines.push('Efeito: Invisibilidade');
                    if (parseInt(meta.healthgain || meta.active_healthgain || 0, 10)) lines.push('Regeneração de vida');
                    if (parseInt(meta.managain || meta.active_managain || 0, 10)) lines.push('Regeneração de mana');

                    const absorbLabels = {
                        physical: 'Physical',
                        magic: 'Magic',
                        fire: 'Fire',
                        ice: 'Ice',
                        earth: 'Earth',
                        energy: 'Energy',
                        death: 'Death',
                        holy: 'Holy',
                        lifedrain: 'Life Drain',
                        manadrain: 'Mana Drain',
                        drown: 'Drown'
                    };
                    const absorbs = { ...(meta.absorbs || {}), ...(meta.active_absorbs || {}) };
                    Object.entries(absorbLabels).forEach(([key, label]) => {
                        const value = parseInt(absorbs[key] || 0, 10) || 0;
                        if (value !== 0) lines.push(`Protection ${label}: ${value > 0 ? '+' : ''}${value}%`);
                    });

                    if (weight > 0) lines.push(`Weight: ${weight.toFixed(2)} oz`);

                    const description = String(meta.description || '').trim();
                    if (description) lines.push(description);

                    return lines.map(escapeTooltipLine).join('<br>');
                }
